{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.warehouse_b2b_performance AS WITH unicom AS ( SELECT awb, MARKETPLACE, marketplace_mapped, shippingpackagecode, order_id, order_name, saleorderitemcode, sku, order_status, order_date, DAYNAME(order_date) AS created_day, order_timestamp, SHIPPING_LAST_UPDATE_TIMESTAMP, shipping_courier, warehouse_name, shipping_status, cancellation_reason, order_type, CASE WHEN SALE_ORDER_ITEM_STATUS = \'PICKING_FOR_INVOICING\' THEN shippingpackagestatus ELSE SALE_ORDER_ITEM_STATUS END AS UC_STATUS, dispatched_timestamp AS UC_Dispatched, dispatch_date, delivered_date, address_line_1, uc_created, category, packed_time FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 where order_name not in (\'HUBLIK2318\',\'HRBRLA0012\') AND order_date::DATE > \'2025-07-30\' ), forward AS ( SELECT \"Shipping Package Code\", created_timestamp, picking_timestamp, picked_timestamp, packed_timestamp, rts_timestamp, manifested_timestamp, dispatched_timestamp AS dispatched_timestamp1, shipped_timestamp, delivered_timestamp, cancelled_timestamp, \"created&dispatch\", \"pick&dispatch\", \"pack&dispatch\", LATEST_STATUS, LAST_UPDATED FROM snitch_db.maplemonk.forward_timestamps where created_timestamp::DATE >= \'2025-07-30\' ), inward AS ( SELECT TO_DATE(\"DATE\", \'DD/MM/YYYY\') AS order_added_date, TYPE AS inward_type, ORDER_NAME AS orderid, ORDERED_ITEMS, UNFULFILLABLE, \"Fulfilled Quantity\", STATE, STORE, BOXES, STATUS, REMARKS, FACILITY, PRIORITY, EWAYBILL, CASE WHEN DISPATCH_TO_STORE like \'%ST%\' or DISPATCH_TO_STORE = \'N/A\' then null else TO_DATE(DISPATCH_TO_STORE, \'DD/MM/YYYY\') end AS dispatch_to_store_date, DISPATCH_TO_YLK AS dispatch_to_ylk_date, LOGISTICS_PARTNER, tat AS manual_tat FROM snitch_db.maplemonk.gs_b2b_uc ), lr_data AS ( SELECT logs_tat as out_logs_tat, l_dc_number as out_dc_number, l_lr_number as out_lr_number, dispatch_type as out_dispatch_type, CASE WHEN expected_date like \'-%\' then null else TO_DATE(expected_date, \'DD/MM/YYYY\') end AS out_expected_delivery_date, TO_DATE(delivered_date, \'DD/MM/YYYY\') AS out_delivered_date, TO_DATE(l_dispatch_date, \'DD/MM/YYYY\') AS out_dispatch_date, shipment_status as out_shipment_status, store_name_logs FROM snitch_db.maplemonk.gs_b2b_logistics ), logsin AS ( SELECT in_dc_no, in_store, in_so_no, in_logs_partner, TO_DATE(in_dispatch_date,\'DD/MM/YYYY\') as in_dispatch_date, TO_DATE(in_expected_date,\'DD/MM/YYYY\') as in_expected_date, TO_DATE(in_delivered_date,\'DD/MM/YYYY\') as in_delivered_date, in_shipment_status FROM snitch_db.maplemonk.gs_b2b_instation ), os_data AS ( SELECT replace(ind_so,\' \',\'\') as ind_so, TO_DATE(date,\'DD/MM/YYYY\') AS sheet_date, dc_number, lr_number FROM snitch_db.maplemonk.logistics_convertor ), main_data AS ( SELECT ue.*, f.*, iw.*, os.* FROM unicom ue LEFT JOIN forward f ON ue.shippingpackagecode = f.\"Shipping Package Code\" LEFT JOIN inward iw ON ue.order_name = iw.orderid LEFT JOIN os_data os ON ue.order_name::string = os.ind_so::string ), sd_data as ( select fresh_day, rpl_day, branch_code, store_name_format, so_code, channel, \"Shipping Address Line 1\" as FINAL_STORE from snitch_db.maplemonk.gs_store_details ), over AS ( SELECT don, soic, facwarehouse, overrulestatus FROM snitch_db.maplemonk.gs_overrule ), mast1 AS ( SELECT md.*, ov.* FROM main_data md LEFT JOIN over ov ON md.saleorderitemcode = ov.soic ), new_status AS ( SELECT m1.*, CASE WHEN overrulestatus = \'DISPATCHED\' THEN created_timestamp END AS dispatchedtimestamp2, CASE WHEN UC_STATUS IN (\'UNFULFILLABLE\', \'DISPATCHED\', \'DELIVERED\', \'SHIPPED\', \'RETURN_EXPECTED\', \'CANCELLED\', \'REPLACED\', \'RETURNED\') THEN UC_STATUS ELSE COALESCE(LATEST_STATUS, UC_STATUS) END AS ITEM_STATUS2, COALESCE(dispatchedtimestamp2, COALESCE(dispatched_timestamp1, UC_Dispatched)) AS dispatched_timestamp, COALESCE(overrulestatus, ITEM_STATUS2) AS ITEM_STATUS, ld.*, li.*, COALESCE(dc_number, li.in_dc_no) AS l_dc_number, COALESCE(m1.lr_number, li.in_so_no) AS l_lr_number, COALESCE(ind_so, li.in_store) AS store_name_input_logs, COALESCE(ld.out_dispatch_date, li.in_dispatch_date) AS lr_dispatch_date, COALESCE(ld.out_delivered_date, li.in_delivered_date) AS l_delivered_date, COALESCE(ld.out_shipment_status, li.in_shipment_status) AS shipment_status, COALESCE(ld.out_expected_delivery_date, li.in_expected_date) AS expected_date, ld.out_dispatch_type AS dispatch_type, sd.*, CASE WHEN order_date >= \'2025-06-01\' and EXTRACT(HOUR,uc_created) < 16 and marketplace_mapped IN (\'ZILO\',\'KNOT\',\'SLIKK\') THEN DATE_TRUNC(\'day\', DATEADD(day, 3, COALESCE(uc_created::timestamp, CURRENT_TIMESTAMP)::date)) + INTERVAL \'16 hours\' WHEN order_date >= \'2025-06-01\' and EXTRACT(HOUR,uc_created) < 16 and marketplace_mapped IN (\'ZILO\',\'KNOT\',\'SLIKK\') THEN DATE_TRUNC(\'day\', DATEADD(day, 4, COALESCE(uc_created::timestamp, CURRENT_TIMESTAMP)::date)) + INTERVAL \'16 hours\' WHEN order_date >= \'2025-06-01\' and EXTRACT(HOUR,uc_created) < 16 and marketplace_mapped = \'MYNTRA_SJIT\' THEN DATE_TRUNC(\'day\', DATEADD(day, 4, COALESCE(uc_created::timestamp, CURRENT_TIMESTAMP)::date)) + INTERVAL \'16 hours\' WHEN order_date >= \'2025-06-01\' and EXTRACT(HOUR,uc_created) < 16 and marketplace_mapped = \'MYNTRA_SJIT\' THEN DATE_TRUNC(\'day\', DATEADD(day, 5, COALESCE(uc_created::timestamp, CURRENT_TIMESTAMP)::date)) + INTERVAL \'16 hours\' WHEN order_date >= \'2025-06-01\' and EXTRACT(HOUR,uc_created) < 16 and order_type in (\'NSO\',\'OTHER\',\'OTHERS\') and marketplace_mapped = \'STORE\' THEN DATE_TRUNC(\'day\', DATEADD(day, 5, COALESCE(uc_created::timestamp, CURRENT_TIMESTAMP)::date)) + INTERVAL \'16 hours\' WHEN order_date >= \'2025-06-01\' and EXTRACT(HOUR,uc_created) < 16 and order_type in (\'FRESH\',\'RPL\') and marketplace_mapped = \'STORE\' THEN DATE_TRUNC(\'day\', DATEADD(day, 1, COALESCE(uc_created::timestamp, CURRENT_TIMESTAMP)::date)) + INTERVAL \'16 hours\' WHEN order_date >= \'2025-06-01\' and EXTRACT(HOUR FROM uc_created) >= 16 and order_type in (\'FRESH\',\'RPL\') and marketplace_mapped = \'STORE\' THEN DATE_TRUNC(\'day\', DATEADD(day, 2, COALESCE(uc_created::timestamp, CURRENT_TIMESTAMP)::date)) + INTERVAL \'16 hours\' WHEN EXTRACT(HOUR,uc_created) < 16 THEN DATE_TRUNC(\'day\', DATEADD(day, 1, COALESCE(uc_created::timestamp, CURRENT_TIMESTAMP)::date)) + INTERVAL \'16 hours\' WHEN EXTRACT(HOUR FROM uc_created) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(day, 2, COALESCE(uc_created::timestamp, CURRENT_TIMESTAMP)::date)) + INTERVAL \'16 hours\' WHEN order_date >= \'2025-06-01\' and EXTRACT(HOUR,uc_created) < 16 THEN DATE_TRUNC(\'day\', DATEADD(day, 2, COALESCE(uc_created::timestamp, CURRENT_TIMESTAMP)::date)) + INTERVAL \'16 hours\' WHEN order_date >= \'2025-06-01\' and EXTRACT(HOUR FROM uc_created) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(day, 3, COALESCE(uc_created::timestamp, CURRENT_TIMESTAMP)::date)) + INTERVAL \'16 hours\' ELSE null END AS TAT, COALESCE( packed_time,packed_timestamp, rts_timestamp) AS wh_processed, CASE WHEN TAT > CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP()) AND ITEM_STATUS IN (\'DISPATCHED\', \'REPLACED\', \'DELIVERED\', \'SHIPPED\', \'RETURNED\') THEN \'FUTURE DATE-COMPLETED\' WHEN TAT > CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP()) AND ITEM_STATUS NOT IN (\'DISPATCHED\', \'REPLACED\', \'DELIVERED\', \'SHIPPED\', \'RETURNED\') THEN \'FUTURE DATE-PENDING\' ELSE CASE WHEN ITEM_STATUS IN (\'DISPATCHED\', \'REPLACED\', \'DELIVERED\', \'SHIPPED\', \'RETURN_EXPECTED\', \'PACKED\', \'MANIFESTED\', \'READY_TO_SHIP\') THEN CASE WHEN wh_processed <= TAT THEN \'WITHIN SLA\' ELSE \'BREACHED\' END WHEN ITEM_STATUS = \'CANCELLED\' THEN CASE WHEN wh_processed IS NULL THEN \'CANCELLED\' ELSE CASE WHEN wh_processed <= TAT THEN \'WITHIN SLA\' ELSE \'BREACHED\' END END WHEN ITEM_STATUS IN (\'CREATED\', \'PICKING\', \'PICKED\', \'PICKING_FOR_INVOICING\', \'FULFILLABLE\') THEN \'BREACHED - PENDING FOR PROCESS\' WHEN ITEM_STATUS = \'UNFULFILLABLE\' THEN \'UNFULFILLABLE\' ELSE \'BREACHED\' END END AS SLA_Status, CASE WHEN TIMESTAMPDIFF(day, TAT, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())) = 0 THEN \'D0\' WHEN TIMESTAMPDIFF(day, TAT, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())) = 1 THEN \'D1\' WHEN TIMESTAMPDIFF(day, TAT, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())) = 2 THEN \'D2\' WHEN TIMESTAMPDIFF(day, TAT, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())) = 3 THEN \'D3\' WHEN TIMESTAMPDIFF(day, TAT, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())) > 3 AND TIMESTAMPDIFF(day, TAT, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())) <= 5 THEN \'D>3\' WHEN TIMESTAMPDIFF(day, TAT, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())) > 5 AND TIMESTAMPDIFF(day, TAT, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())) <= 7 THEN \'D>5\' WHEN TIMESTAMPDIFF(day, TAT, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())) > 7 AND TIMESTAMPDIFF(day, TAT, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())) <= 9 THEN \'D>7\' WHEN TIMESTAMPDIFF(day, TAT, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())) > 9 THEN \'D>9\' ELSE \'Unknown Ageing\' END AS Ageing, CASE WHEN inward_type = \'FRESH ALLOCATION\' THEN CASE WHEN EXTRACT(HOUR FROM order_timestamp) < 16 THEN \'WITHIN SLA\' ELSE \'BREACHED\' END WHEN inward_type = \'RPL\' THEN CASE WHEN EXTRACT(HOUR FROM order_timestamp) < 14 THEN \'WITHIN SLA\' ELSE \'BREACHED\' END ELSE CASE WHEN EXTRACT(HOUR FROM order_timestamp) < 23 THEN \'NO SLA\' ELSE \'NO SLA\' END END AS creation_sla, CASE WHEN rts_timestamp IS NULL THEN DATE_TRUNC(\'day\', DATEADD(day, 0, COALESCE(TAT::timestamp, CURRENT_TIMESTAMP))) + INTERVAL \'23 hours\' WHEN EXTRACT(HOUR FROM rts_timestamp) < 16 THEN DATE_TRUNC(\'day\', DATEADD(day, 0, COALESCE(rts_timestamp::timestamp, CURRENT_TIMESTAMP))) + INTERVAL \'23 hours\' WHEN EXTRACT(HOUR FROM rts_timestamp) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(day, 1, COALESCE(rts_timestamp::timestamp, CURRENT_TIMESTAMP))) + INTERVAL \'23 hours\' END AS handover_tat, CASE WHEN handover_tat > CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP()) THEN \'FUTURE DATE-PENDING\' WHEN sheet_date <= handover_tat::date THEN \'WITHIN SLA\' ELSE \'BREACHED\' END AS handover_sla, CASE WHEN state = \'Hyderabad\' THEN DATE_TRUNC(\'day\', DATEADD(day, 3, handover_tat)) + INTERVAL \'23 hours\' WHEN state = \'Odisha\' THEN DATE_TRUNC(\'day\', DATEADD(day, 4, handover_tat)) + INTERVAL \'23 hours\' WHEN state = \'Tamil Nadu\' THEN DATE_TRUNC(\'day\', DATEADD(day, 3, handover_tat)) + INTERVAL \'23 hours\' WHEN state = \'Andhra Pradesh\' THEN DATE_TRUNC(\'day\', DATEADD(day, 3, handover_tat)) + INTERVAL \'23 hours\' WHEN state = \'Gujarat\' THEN DATE_TRUNC(\'day\', DATEADD(day, 5, handover_tat)) + INTERVAL \'23 hours\' WHEN FINAL_STORE = \'CITYCENTRE\' THEN DATE_TRUNC(\'day\', DATEADD(day, 2, handover_tat)) + INTERVAL \'23 hours\' WHEN state = \'Karnataka\' AND FINAL_STORE NOT IN (\'CITYCENTRE\') THEN DATE_TRUNC(\'day\', DATEADD(day, 1, handover_tat)) + INTERVAL \'23 hours\' WHEN state = \'Kerala\' THEN DATE_TRUNC(\'day\', DATEADD(day, 2, handover_tat)) + INTERVAL \'23 hours\' WHEN state = \'Maharashtra\' THEN DATE_TRUNC(\'day\', DATEADD(day, 4, handover_tat)) + INTERVAL \'23 hours\' WHEN state = \'Madhya Pradesh\' THEN DATE_TRUNC(\'day\', DATEADD(day, 5, handover_tat)) + INTERVAL \'23 hours\' WHEN state = \'Rajasthan\' THEN DATE_TRUNC(\'day\', DATEADD(day, 5, handover_tat)) + INTERVAL \'23 hours\' WHEN state = \'Uttarakhand\' THEN DATE_TRUNC(\'day\', DATEADD(day, 6, handover_tat)) + INTERVAL \'23 hours\' WHEN state = \'Uttar Pradesh\' THEN DATE_TRUNC(\'day\', DATEADD(day, 5, handover_tat)) + INTERVAL \'23 hours\' WHEN state = \'Delhi\' THEN DATE_TRUNC(\'day\', DATEADD(day, 5, handover_tat)) + INTERVAL \'23 hours\' ELSE TAT END::TIMESTAMP_NTZ(9) AS logistics_tat, CASE WHEN logistics_tat > CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP()) THEN \'FUTURE DATE-PENDING\' WHEN l_delivered_date IS NULL THEN \'BREACHED-PENDING FOR PROCESS\' WHEN l_delivered_date > logistics_tat THEN \'BREACHED\' WHEN l_delivered_date <= logistics_tat THEN \'WITHIN SLA\' ELSE \'BREACHED\' END AS logistics_sla, TIMESTAMPDIFF(day, handover_tat, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())) AS Logistics_ageing, TIMESTAMPDIFF(day, logistics_tat, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())) AS delivery_ageing, CASE WHEN LOWER(status) = \'on hold\' THEN \'ON-HOLD\' WHEN (status = \'Cancelled\') THEN \'CANCELLATION-PENDING-POST-DISPATCH\' WHEN (status = \'Cancelled\' OR (ITEM_STATUS NOT IN (\'DISPATCHED\', \'MANIFESTED\', \'READY_TO_SHIP\', \'PACKED\', \'SHIPPED\') AND (l_lr_number IS NOT NULL OR LOWER(status) LIKE \'%dispatched%\'))) AND order_date <= DATE_TRUNC(\'day\', DATEADD(day, -5, CURRENT_DATE)) THEN \'CANCELLATION-PENDING-POST-DISPATCH\' WHEN ITEM_STATUS IN (\'UNFULFILLABLE\') THEN \'CANCELLATION-PENDING-UF\' WHEN LOWER(shipment_status) = \'delivered\' THEN \'DELIVERED\' WHEN LOWER(shipment_status) IN (\'failed delivered\', \'in-transit\', \'out for delivery\') THEN \'INTRANSIT\' WHEN LOWER(SLA_Status) LIKE \'%future%\' AND LOWER(SLA_Status) LIKE \'%pending%\' AND ITEM_STATUS NOT IN (\'PACKED\', \'DISPATCHED\', \'MANIFESTED\', \'READY_TO_SHIP\', \'SHIPPED\') THEN \'WH-FUTURETAT\' WHEN LOWER(SLA_Status) LIKE \'%process%\' THEN \'WH-PENDENCY\' WHEN dispatch_to_ylk_date IS NOT NULL AND LOWER(status) = \'dispatched to wh\' AND shipment_status IS NULL THEN \'WH-YLK-PENDING\' WHEN dispatch_to_ylk_date IS NOT NULL AND LOWER(status) = \'dispatched to store\' AND shipment_status IS NULL THEN \'MISSING/INCORRECT-DISPATCH\' WHEN l_lr_number IS NOT NULL AND shipment_status IS NULL THEN \'MISSING_LOGS_TRACKER\' WHEN (ITEM_STATUS IN (\'DISPATCHED\', \'MANIFESTED\', \'READY_TO_SHIP\', \'PACKED\', \'SHIPPED\') AND l_lr_number IS NULL) OR (ITEM_STATUS IN (\'DISPATCHED\', \'MANIFESTED\', \'READY_TO_SHIP\', \'PACKED\', \'SHIPPED\') AND state = \'Karnataka\' AND LOWER(shipment_status) NOT IN (\'dispatched\', \'delivered\', \'in-transit\')) THEN \'PICKUPPENDING\' ELSE shipment_status END AS final_status, CASE WHEN final_status LIKE \'%WH%\' THEN ITEM_STATUS WHEN LOWER(shipment_status) = \'delivered\' THEN logistics_sla WHEN final_status = \'INTRANSIT\' THEN shipment_status WHEN final_status = \'PICKUPPENDING\' AND LOWER(status) IN (\'on hold\', \'duplicate\', \'ready to dispatch\', \'rts-logic\') THEN status END AS detailed_status FROM mast1 m1 LEFT JOIN lr_data ld ON m1.lr_number = ld.out_lr_number LEFT JOIN sd_data sd ON m1.store = sd.store_name_format LEFT JOIN logsin li ON m1.order_name = li.in_so_no ) SELECT * FROM new_status WHERE ((marketplace_mapped like \'%STORE%\' or marketplace_mapped in (\'MYNTRA_SJIT\',\'ZILO\',\'KNOT\',\'SLIKK\',\'SNITCH HQ\') or marketplace like \'%B2B%\' or marketplace_mapped like \'%M-NO%\' ) or (marketplace_mapped like \'%TRANSFERS%\' and order_name not like \'%BLOCK%\' )) and item_status not in (\'CANCELLED\') ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            